begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('99999999-9999-4999-8999-999999999999','tutor-a@example.invalid'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','tutor-b@example.invalid');
select ok((select relrowsecurity from pg_class where oid='public.tutor_conversations'::regclass),'Conversation RLS');
select ok((select relrowsecurity from pg_class where oid='public.tutor_messages'::regclass),'Message RLS');
select ok((select relrowsecurity from pg_class where oid='public.tutor_requests'::regclass),'Request ledger RLS');
select ok((select relrowsecurity from pg_class where oid='public.ai_usage'::regclass),'Usage RLS');
select ok((select relrowsecurity from pg_class where oid='public.entitlements'::regclass),'Entitlement RLS');
select ok((select relrowsecurity from pg_class where oid='public.tutor_policy'::regclass),'Policy RLS');
set local role anon;
select throws_ok('select * from tutor_messages','42501',null,'Guest cannot read messages');
select throws_ok('select * from ai_usage','42501',null,'Guest cannot read usage');
select throws_ok('select * from tutor_policy','42501',null,'Guest cannot read private model policy');
select throws_ok($$select delete_tutor_conversation('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001')$$,'42501',null,'Guest cannot call private RPC');
reset role;
update tutor_policy set policy=policy||'{"enabled":true,"model":"test-only","tariff":{"version":"synthetic","source":"https://example.invalid","verifiedAt":"2026-10-14T00:00:00Z","input":5000,"output":25000,"cacheRead":500,"cacheWrite5m":6250,"cacheWrite1h":10000}}';
create temp table tutor_test_policy_revision as select revision from tutor_policy;
update tutor_policy set revision=0;
select is((select revision from tutor_policy),(select revision from tutor_test_policy_revision),'Even backend edits cannot reset policy revision');
update tutor_policy set policy=jsonb_set(policy,'{effort}','"low"');
select is((select revision from tutor_policy),(select revision+1 from tutor_test_policy_revision),'Policy edits always increment revision');
set local role service_role;
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','subscription','Free tutor disabled');
insert into entitlements(user_id,entitlement,active,expires_at,store) values('99999999-9999-4999-8999-999999999999','premium',true,now()+interval '1 day','manual'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','max',true,now()+interval '1 day','manual');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'tier','premium','Active Premium admitted');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','busy','Identical in-flight request cannot run twice');
select is(reserve_tutor_request('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','conflict','Global request ID cannot be stolen');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','busy','Only one active model request per account');
select ok(not finish_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001',gen_random_uuid(),'complete','{}','{}'),'Wrong lease cannot finish');
select ok(finish_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001',(select lease from tutor_requests where id='10000000-0000-4000-8000-000000000001'),'complete','{"inputTokens":100,"outputTokens":20,"cacheReadTokens":200,"cacheWrite5mTokens":300,"cacheWrite1hTokens":0,"unknownCacheWriteTokens":0,"costNanoUsd":2975000,"estimated":false}','{"text":"answer","examples":[],"errors":[],"status":"complete"}'),'Finish records actual token cost');
select ok(finish_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001',(select lease from tutor_requests where id='10000000-0000-4000-8000-000000000001'),'complete','{"inputTokens":100,"outputTokens":20,"cacheReadTokens":200,"cacheWrite5mTokens":300,"cacheWrite1hTokens":0,"unknownCacheWriteTokens":0,"costNanoUsd":2975000,"estimated":false}','{"text":"answer","examples":[],"errors":[],"status":"complete"}'),'Same finalization is idempotent');
select is((select requests from ai_usage where user_id='99999999-9999-4999-8999-999999999999'),1,'One request charged');
select is((select cost_nano_usd from ai_usage where user_id='99999999-9999-4999-8999-999999999999'),2975000::bigint,'Integer Nano-USD sum');
select is((select count(*)::integer from tutor_messages),2,'One user and one assistant message');
select is((select user_text from tutor_requests),'','Ledger drops completed learner text');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'replay','true','Completed request replays');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('c',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','conflict','Changed request ID rejected');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('c',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','context','Hint/task/language scope cannot change silently');
select is(reserve_tutor_request('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','context','Other account cannot use conversation');
update tutor_policy set policy=jsonb_set(policy,'{requestsPerMinute}','1');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','rate','Minute rate limit');
update tutor_policy set policy=jsonb_set(policy,'{premium,requests}','1');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','quota','Daily request quota');
update tutor_policy set policy=jsonb_set(jsonb_set(policy,'{premium,requests}','30'),'{requestsPerMinute}','60');
update entitlements set expires_at=now()-interval '1 second' where user_id='99999999-9999-4999-8999-999999999999';
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','subscription','Expired subscription rejected');
update entitlements set expires_at=now()+interval '1 day',active=false where user_id='99999999-9999-4999-8999-999999999999';
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','subscription','Revoked subscription rejected');
update entitlements set active=true;
update tutor_policy set policy=jsonb_set(policy,'{premium,costNanoUsd}','2975000');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','budget','Account cost budget reserves worst case');
update tutor_policy set policy=jsonb_set(jsonb_set(policy,'{premium,costNanoUsd}','1000000000'),'{globalDailyCostNanoUsd}','2975000');
select is(reserve_tutor_request('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','budget','Global cost budget');
update tutor_policy set policy=jsonb_set(policy,'{globalDailyCostNanoUsd}','10000000000');
select is(reserve_tutor_request('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'tier','max','Max entitlement takes precedence');
update tutor_requests set lease_until=now()-interval '1 second' where id='10000000-0000-4000-8000-000000000002';
select ok(reserve_tutor_request('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','10000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000) ? 'lease','Expired process recovered and lock released');
select is((select cost from tutor_requests where id='10000000-0000-4000-8000-000000000002'),10000000::bigint,'Expired process billed conservative reserved cost');
select is((select usage->>'estimated' from tutor_requests where id='10000000-0000-4000-8000-000000000002'),'true','Unknown usage labelled estimated');
set local role authenticated;
set local request.jwt.claims='{"sub":"99999999-9999-4999-8999-999999999999","role":"authenticated"}';
select is((select count(*)::integer from tutor_conversations),1,'Only own conversations');
select is((select count(*)::integer from tutor_messages),2,'Only own messages');
select is((select count(*)::integer from entitlements),1,'Only own entitlement');
select is((select count(*)::integer from ai_usage),1,'Only own usage');
select throws_ok('select * from tutor_requests','42501',null,'Private reservation leases are not exposed');
select throws_ok('update entitlements set active=true','42501',null,'Client cannot create subscription');
select throws_ok('delete from ai_usage','42501',null,'Client cannot reset quota');
select throws_ok('delete from tutor_messages','42501',null,'Client cannot rewrite model history');
select throws_ok($$select delete_tutor_conversation('99999999-9999-4999-8999-999999999999','20000000-0000-4000-8000-000000000001')$$,'42501',null,'Only authenticated Edge calls private deletion');
set local role service_role;
select ok(not delete_tutor_conversation('99999999-9999-4999-8999-999999999999','20000000-0000-4000-8000-000000000002'),'Foreign deletion refused');
select ok(delete_tutor_conversation('99999999-9999-4999-8999-999999999999','20000000-0000-4000-8000-000000000001'),'Own deletion succeeds');
select is((select count(*)::integer from tutor_messages where conversation_id='20000000-0000-4000-8000-000000000001'),0,'Deletion erases messages');
select ok((select result is null and conversation_id is null and user_text='' from tutor_requests where id='10000000-0000-4000-8000-000000000001'),'Deletion erases cached response and pending text');
select is((select requests from ai_usage where user_id='99999999-9999-4999-8999-999999999999'),1,'Conversation deletion retains quota');
select is(reserve_tutor_request('99999999-9999-4999-8999-999999999999','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'{}','hi',(select revision from tutor_policy),10000000)->>'error','deleted','Deleted request cannot resurrect answer');
reset role;
delete from auth.users where id in ('99999999-9999-4999-8999-999999999999','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select is((select count(*)::integer from tutor_requests),0,'Account deletion removes ledger');
select is((select count(*)::integer from tutor_messages),0,'Account deletion removes messages');
select is((select count(*)::integer from entitlements),0,'Account deletion removes entitlements');
select is((select count(*)::integer from ai_usage),0,'Account deletion removes usage');
set local role authenticated;
set local request.jwt.claims='{"sub":"99999999-9999-4999-8999-999999999999","role":"authenticated"}';
select throws_ok($$select tutor_account_status('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$,'42501',null,'Client cannot query other quota through private RPC');
reset role;
select * from finish();
rollback;
